from pathlib import Path
Path("story.json").write_text('[\n  {\n    "id": "hook",\n    "duration": 7,\n    "title": "Human control, made visible",\n    "sentences": [\n      "A reviewer changes an owner. The original evidence stays intact. Human control is the starting point."\n    ]\n  },\n  {\n    "id": "title",\n    "duration": 9,\n    "title": "Architecture Governance Copilot",\n    "sentences": [\n      "Architecture Governance Copilot helps project teams turn architecture work into an accountable governance record.",\n      "We are Two Tokens One Brain."\n    ]\n  },\n  {\n    "id": "process",\n    "duration": 18,\n    "title": "The problem: fragmented governance work",\n    "sentences": [\n      "Project teams prepare a Solution Intent in Confluence. Domain Architects review it in Teams, while Azure DevOps tracks governance work.",\n      "Across these handoffs, decisions, evidence and ownership become scattered. Teams reconstruct the record manually."\n    ]\n  },\n  {\n    "id": "solution",\n    "duration": 14,\n    "title": "Two activities, explicit human checkpoints",\n    "sentences": [\n      "We support two activities: drafting from confirmed context, and structuring an independent review.",\n      "People inspect evidence, edit proposals and confirm the outputs."\n    ]\n  },\n  {\n    "id": "architecture",\n    "duration": 24,\n    "title": "System architecture",\n    "sentences": [\n      "The architecture places the interface in Service Bench, and the backend and database in SKE.",\n      "Adapters connect Confluence, Azure DevOps and AI Factory. Teams transcripts are imported manually.",\n      "SKE sends telemetry to COP for Grafana and Kibana.",\n      "Formal architecture approval remains with the Domain Architect."\n    ]\n  },\n  {\n    "id": "draft",\n    "duration": 27,\n    "title": "1. Prepare and confirm an SI draft",\n    "sentences": [\n      "Let us follow the project team\\u2019s journey. I open the project context, with its selected template, repository revision and governance information.",\n      "I save supporting evidence, then confirm the package and generate a Solution Intent draft.",\n      "The draft requires human confirmation. It is not published automatically. Governance review starts separately."\n    ]\n  },\n  {\n    "id": "inputs",\n    "duration": 19,\n    "title": "2. Select and confirm review inputs",\n    "sentences": [\n      "For review, I select an authoritative Solution Intent, import the meeting transcript, and load review metadata.",\n      "These are independent inputs. I confirm the exact package before analysis produces an evidence-linked proposal for Human Review."\n    ]\n  },\n  {\n    "id": "human",\n    "duration": 33,\n    "title": "3. Exercise human judgment",\n    "sentences": [\n      "Here is the human checkpoint. Riley committed to documenting retry controls. I change the action owner to Taylor Kim.",\n      "The original quote remains unchanged, and the interface identifies my edit before confirmation.",\n      "I also exclude the retention finding from this record. Exclusion does not mean resolution or approval.",\n      "The outcome remains Changes Requested. I explicitly confirm the reviewed record to generate outputs."\n    ]\n  },\n  {\n    "id": "outputs",\n    "duration": 23,\n    "title": "4. Follow evidence into the outputs",\n    "sentences": [\n      "The change summary preserves both choices. Now follow one action: Riley\\u2019s original quote, Taylor as the confirmed owner, the actual minutes entry, and the matching work-item preview.",\n      "This comparison makes the source, human judgment and generated record inspectable together."\n    ]\n  },\n  {\n    "id": "delivery",\n    "duration": 29,\n    "title": "5. Deliver through explicit controls",\n    "sentences": [\n      "Delivery has its own confirmation boundary. I preview the request and check its owner, due date, parent reference and evidence.",\n      "The readable summary and JSON represent the same request. I confirm it, then create the work item.",\n      "The receipt shows read-back verification, and the completed action is protected from direct resubmission."\n    ]\n  },\n  {\n    "id": "invalidation",\n    "duration": 19,\n    "title": "6. Protect against stale outputs",\n    "sentences": [\n      "Now I return to the transcript and add new context. Inputs changed: the previous outputs are invalidated.",\n      "The updated package needs renewed analysis and human confirmation. This protects record consistency without undoing a completed delivery."\n    ]\n  },\n  {\n    "id": "value",\n    "duration": 8,\n    "title": "What we strengthened",\n    "sentences": [\n      "Judge feedback led to visible edits, evidence tracing and stale-output protection. We also added controlled delivery."\n    ]\n  },\n  {\n    "id": "close",\n    "duration": 8,\n    "title": "Two Tokens One Brain",\n    "sentences": [\n      "Less reconstruction. Easier verification. Business validation comes next. Two Tokens One Brain."\n    ]\n  }\n]\n')
